import{_ as a,a0 as o,w as i,s as l,ao as r,I as p,x as n,a1 as s,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"开启 Ubuntu 系统自动升级 | LCTT x X-CMD","titleTemplate":false,"description":"开启 Ubuntu 系统自动升级 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"开启 Ubuntu 系统自动升级 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"开启 Ubuntu 系统自动升级 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150916 Enable Automatic System Updates In Ubuntu","title":"开启 Ubuntu 系统自动升级","tag":"201509","desc":""},"relativePath":"201509/20150916 Enable Automatic System Updates In Ubuntu.md","filePath":"[post].md"}'),d={name:"201509/20150916 Enable Automatic System Updates In Ubuntu.md"};function m(b,t,f,U,T,g){const u=o("Link");return i(),l("div",null,[t[16]||(t[16]=r('<h1 id="开启-ubuntu-系统自动升级" tabindex="-1">开启 Ubuntu 系统自动升级 <a class="header-anchor" href="#开启-ubuntu-系统自动升级" aria-label="Permalink to “开启 Ubuntu 系统自动升级”">​</a></h1><p>在学习如何开启Ubuntu系统自动升级之前，先解释下为什么需要自动升级。</p><p>默认情况下，ubuntu每天一次检查更新。但是一周只会弹出一次软件升级提醒，除非当有安全性升级时，才会立即弹出。所以，如果你已经使用Ubuntu一段时间，你肯定很熟悉这个画面：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/09/Software-Update-Ubntu.png" alt="Ubuntu软件升级提醒"></p><p>但是做为一个正常桌面用户，根本不会去关心有什么更新细节。而且这个提醒完全就是浪费时间，你肯定信任Ubuntu提供的升级补丁，对不对？所以，大部分情况你肯定会选择“现在安装”，对不对？</p><p>所以，你需要做的就只是点一下升级按钮。现在，明白为什么需要自动系统升级了吧？开启自动系统升级意味着所有最新的更新都会自动下载并安装，并且没有请求确认。是不是很方便？</p><h3 id="开启ubuntu自动升级" tabindex="-1">开启Ubuntu自动升级 <a class="header-anchor" href="#开启ubuntu自动升级" aria-label="Permalink to “开启Ubuntu自动升级”">​</a></h3><p>演示使用Ubuntu15.04，Ubuntu 14.04步骤类似。</p><p>打开Unity Dash ，找到软件&amp;更新：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/08/Software_Update_Ubuntu.jpeg" alt="Ubuntu 软件升级设置"></p><p>打开软件资源设置，切换到升级标签：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/09/Software-Update-Ubntu-1.png" alt="Ubuntu 软件升级设置"></p><p>可以发现，默认设置就是每日检查并立即提醒安全升级。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/09/Software-Update-Ubntu-2.png" alt="改变软件更新频率"></p><p>改变 ‘当有安全升级’和‘当有其他升级’的选项为：下载并自动安装。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/09/Software-Update-Ubntu-3.png" alt="Automatic updates in Ubuntu"></p>',16)),p("p",null,[t[1]||(t[1]=n("关闭对话框完成设定。这样每次Ubuntu检查更新后就会自动升级。事实上，这篇文章十分类似",-1)),s(u,{href:"http://itsfoss.com/ubuntu-notify-updates-frequently/"},{default:e(()=>[...t[0]||(t[0]=[n("改变Ubuntu升级提醒频率",-1)])]),_:1}),t[2]||(t[2]=n("。",-1))]),t[17]||(t[17]=p("p",null,"你喜欢自动升级还是手动安装升级呢？欢迎评论。",-1)),t[18]||(t[18]=p("hr",null,null,-1)),p("p",null,[t[4]||(t[4]=n("via: ",-1)),s(u,{href:"http://itsfoss.com/automatic-system-updates-ubuntu/"},{default:e(()=>[...t[3]||(t[3]=[n("http://itsfoss.com/automatic-system-updates-ubuntu/",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=n("作者：",-1)),s(u,{href:"http://itsfoss.com/author/abhishek/"},{default:e(()=>[...t[5]||(t[5]=[n("Abhishek",-1)])]),_:1}),t[9]||(t[9]=n(" 译者：",-1)),s(u,{href:"http://vicyu.net"},{default:e(()=>[...t[6]||(t[6]=[n("Vic020/VicYu",-1)])]),_:1}),t[10]||(t[10]=n(" 校对：",-1)),s(u,{href:"https://github.com/wxy"},{default:e(()=>[...t[7]||(t[7]=[n("wxy",-1)])]),_:1})]),p("p",null,[t[13]||(t[13]=n("本文由 ",-1)),s(u,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[11]||(t[11]=[n("LCTT",-1)])]),_:1}),t[14]||(t[14]=n(" 原创编译，",-1)),s(u,{href:"https://linux.cn/"},{default:e(()=>[...t[12]||(t[12]=[n("Linux中国",-1)])]),_:1}),t[15]||(t[15]=n(" 荣誉推出",-1))])])}const S=a(d,[["render",m]]);export{w as __pageData,S as default};
